window.kbPageData["views/entry/k-aa89d7cbe7587c24"] = {"key":"entry/k-aa89d7cbe7587c24","state":{"route":"entry/k-aa89d7cbe7587c24"},"node":{"id":"k-aa89d7cbe7587c24","mode":"k","title":"国务院《城市更新“十五五”规划》（5 月 28 日）","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["regional"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["公共管理"],"时间索引":["年度事件或数据"],"来源主题":["重要文件"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"国务院《城市更新“十五五”规划》（5 月 28 日）","slug":"832da6461321"}],"directorySummary":"考点十三 国务院《城市更新“十五五”规划》（5 月 28 日）\n这是城市更新领域第一部国家级专项规划，也是“十五五”规划纲要公布后第一个分领域专项\n规划。坚持稳中求进、以人民为中心、系统观念、规划引领、统筹发展和安全、保护第一应保\n尽保以用促保。到 2030 年城市更新行动取得重要进展、开发建设方式…","sources":[{"id":"d49d978dc4a40f98","label":"国务院《城市更新“十五五”规划》（5 月 28 日）","topic":"重要文件","category":"时政","text":"考点十三 国务院《城市更新“十五五”规划》（5 月 28 日）\n这是城市更新领域第一部国家级专项规划，也是“十五五”规划纲要公布后第一个分领域专项\n规划。坚持稳中求进、以人民为中心、系统观念、规划引领、统筹发展和安全、保护第一应保\n尽保以用促保。到 2030 年城市更新行动取得重要进展、开发建设方式转型初见成效；到 2035\n年创新、宜居、美丽、韧性、文明、智慧的现代化人民城市基本建成。部署培育城市发展新动\n能等 6 方面重点任务、7 方面政策举措和“好房子”建设改造等 14 项重大工程，构建中央统\n筹、省负总责、城市抓落实的工作格局。","source":{"doc":"4e539a366dce19555ccf","first":14,"last":15,"page":14,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"regional","title":"区域协调与城乡融合"}],"units":{"k-aa89d7cbe7587c24":[]}};
